class Solution { void add(int[] b,int i){for(;i<b.length;i+=i&-i)b[i]++;} int sum(int[] b,int i){int s=0;for(;i>0;i-=i&-i)s+=b[i];return s;} public List<Integer> countSmaller(int[] a){int[] v=a.clone();Arrays.sort(v);List<Integer> u=new ArrayList<>();for(int x:v)if(u.isEmpty()||u.get(u.size()-1)!=x)u.add(x);int[] b=new int[u.size()+1];Integer[] out=new Integer[a.length];for(int k=a.length-1;k>=0;k--){int r=Collections.binarySearch(u,a[k]);out[k]=sum(b,r);add(b,r+1);}return Arrays.asList(out);} }
